"""Small Markdown primitives shared by the document converters."""

import re
from urllib.parse import quote

MAX_TABLE_CELLS = 1_000_000


def escape_text(text: str) -> str:
    """Quote literal text without escaping Markdown generated by a converter."""
    # Prevent a second HTML-entity decoding pass by Markdown renderers.
    text = re.sub(r'&(?=(?:#[0-9]+|#[xX][0-9a-fA-F]+|[A-Za-z][A-Za-z0-9]+);)', '&amp;', text)
    text = re.sub(r'([\\`*_~\[\]<>])', r'\\\1', text)
    text = re.sub(r'(?m)^(\s*)([#>+\-=])', r'\1\\\2', text)
    return re.sub(r'(?m)^(\s*\d+)([.)])(?=\s)', r'\1\\\2', text)


def link(text: str, destination: str) -> str:
    # Percent-encode delimiters that would terminate a Markdown destination.
    url = quote(destination, safe="/:?#@!$&'*+,;=%~_-.")
    return f'[{text}]({url})'


def inline(text: str, bold=False, italic=False, destination=None) -> str:
    match = re.fullmatch(r'(\s*)(.*?)(\s*)', text, re.DOTALL)
    if not match or not match[2]:
        return text
    leading, core, trailing = match.groups()
    core = escape_text(core)
    marker = '***' if bold and italic else '**' if bold else '*' if italic else ''
    core = marker + core + marker
    if destination:
        core = link(core, destination)
    return leading + core + trailing


def code_span(text: str) -> str:
    runs = re.findall(r'`+', text)
    fence = '`' * (max(map(len, runs), default=0) + 1)
    text = text.replace('\r\n', ' ').replace('\n', ' ').replace('\r', ' ')
    if text.startswith('`') or text.endswith('`') or (text.startswith(' ') and text.endswith(' ') and text.strip()):
        text = ' ' + text + ' '
    return fence + text + fence


def code_block(text: str, language='') -> str:
    fence = '`' * max(3, max(map(len, re.findall(r'`+', text)), default=0) + 1)
    return f'{fence}{language}\n{text}' + ('' if text.endswith('\n') else '\n') + fence


def pipe_table(rows: list[list[str]]) -> str:
    """Render already-escaped cells; merged continuations are empty cells."""
    width = max(map(len, rows), default=0)
    if not width:
        return ''
    if width * len(rows) > MAX_TABLE_CELLS:
        raise ValueError(f'Table exceeds the {MAX_TABLE_CELLS:,}-cell output limit')
    lines = []
    for row in rows:
        cells = []
        for value in row + [''] * (width - len(row)):
            value = value.replace('\r\n', '\n').replace('\r', '\n')
            value = re.sub(r'[ \t]+', ' ', value).strip().replace('\n', '<br>')
            cells.append(value.replace('|', '\\|'))
        lines.append('| ' + ' | '.join(cells) + ' |')
    lines.insert(1, '| ' + ' | '.join(['---'] * width) + ' |')
    return '\n'.join(lines)


def join_blocks(blocks: list[tuple[str, bool]]) -> str:
    result = ''
    previous_list = False
    for text, is_list in blocks:
        if not text:
            continue
        if result:
            result += '\n' if previous_list and is_list else '\n\n'
        result += text
        previous_list = is_list
    return result.strip('\n')


def list_item(text: str, marker: str, indent=0) -> str:
    lines = text.strip('\n').split('\n')
    prefix = ' ' * indent + marker + ' '
    continuation = ' ' * len(prefix)
    return prefix + lines[0] + ''.join('\n' + (continuation + line if line else '') for line in lines[1:])
